
UPDATE QQTT_QQTT_00000200 SET QQTT_QQTT_00000200.DIS_TypeArea = ISNULL((SELECT TOP 1 PPRR_PPRR_00000100.DIS_TypeArea FROM PPRR_PPRR_00000100 WHERE QQTT_QQTT_00000200.PrdRef = PPRR_PPRR_00000100.PrdRef), 3)
UPDATE QQTT_QQTT_00000200 SET QQTT_QQTT_00000200.DIS_MatQnty = ISNULL((SELECT TOP 1 MMNN_PPOO_00000300.StdQuan FROM MMNN_PPOO_00000300 WHERE MMNN_PPOO_00000300.PrdRef = QQTT_QQTT_00000200.PrdRef AND MMNN_PPOO_00000300.RouRef = '' AND MMNN_PPOO_00000300.CostType = 0 AND MMNN_PPOO_00000300.CType = 100), 0)
UPDATE QQTT_QQTT_00000200 SET QQTT_QQTT_00000200.DIS_MatUCost = QQTT_QQTT_00000200.DIS_MatCost / QQTT_QQTT_00000200.DIS_MatQnty WHERE QQTT_QQTT_00000200.DIS_MatQnty > 0
